INSERT INTO hotels (hotel_id, name, city, district, geo_lat, geo_lng, star_rating, user_rating, user_rating_count, amenities_json, address_json, policies_json, description, capacity_estimate) VALUES
('HB-DPS-KEOLLN7A3I', 'Alila Seminyak', 'Bali', 'Seminyak', -8.6917, 115.1629, 4, 4.3, 892, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","beach_access"]', '{"street":"Jl. Taman Ganesha No.9","city":"Seminyak","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Contemporary beachfront resort in Seminyak with modern design and ocean views. Note: Some rooms have reported AC performance issues during humid season.', 80),
('HB-DPS-Q4KUTKSHCG', 'W Bali Seminyak', 'Bali', 'Seminyak', -8.6952, 115.1638, 5, 4.6, 1247, '["wifi","air_conditioning","dehumidifier","minifridge","pool","spa","restaurant","gym","beach_access","bar"]', '{"street":"Jl. Petitenget","city":"Seminyak","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Stylish luxury beachfront resort with vibrant atmosphere and excellent dining options.', 120),
('HB-DPS-GWON4OSFHE', 'Double-Six Luxury Hotel', 'Bali', 'Seminyak', -8.6898, 115.1655, 4, 4.4, 763, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","beach_access","rooftop_bar"]', '{"street":"Jl. Double Six","city":"Seminyak","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Modern hotel with rooftop infinity pool and stunning sunset views over Double Six beach.', 95),
('HB-DPS-63EE6VBHTP', 'The Legian Bali', 'Bali', 'Seminyak', -8.6923, 115.1642, 5, 4.7, 1089, '["wifi","air_conditioning","humidity_control","minifridge","pool","spa","restaurant","gym","beach_access","butler_service"]', '{"street":"Jl. Kayu Aya","city":"Seminyak","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Exclusive beachfront resort offering understated luxury and personalized service.', 75),
('HB-DPS-C33EXCPR4E', 'Courtyard Marriott Seminyak', 'Bali', 'Seminyak', -8.6941, 115.1621, 4, 4.2, 654, '["wifi","air_conditioning","minifridge","pool","restaurant","gym","business_center"]', '{"street":"Jl. Camplung Tanduk","city":"Seminyak","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Reliable international brand hotel with modern amenities and central Seminyak location.', 110),
('HB-DPS-GARGELWTOF', 'Grand Inna Kuta', 'Bali', 'Kuta', -8.7184, 115.1686, 3, 3.8, 542, '["wifi","air_conditioning","minifridge","pool","restaurant"]', '{"street":"Jl. Pantai Kuta","city":"Kuta","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Beachfront hotel near BIMC Hospital with basic amenities and convenient location.', 150),
('HB-DPS-PX46KA7PUK', 'Hard Rock Hotel Bali', 'Bali', 'Kuta', -8.7201, 115.1695, 4, 4.5, 1821, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","kids_club","live_music"]', '{"street":"Jl. Pantai Kuta","city":"Kuta","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Iconic rock-themed resort near BIMC Hospital with entertainment and family facilities.', 180),
('HB-DPS-NHC72QI7SO', 'Bali Dynasty Resort', 'Bali', 'Kuta', -8.7163, 115.1702, 4, 4.3, 987, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","kids_club","waterslide"]', '{"street":"Jl. Kartika Plaza","city":"Kuta","state":"Bali","postal_code":"80361","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Family-friendly resort near BIMC Hospital with extensive pool facilities and activities.', 160),
('HB-DPS-OHFXHXTOGL', 'Alila Ubud', 'Bali', 'Ubud', -8.5237, 115.2641, 5, 4.8, 1456, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","yoga","valley_view"]', '{"street":"Desa Melinggih Kelod","city":"Ubud","state":"Bali","postal_code":"80571","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Award-winning hillside resort with spectacular valley views and tranquil ambiance.', 65),
('HB-DPS-46LQ4EHXKF', 'Maya Ubud Resort & Spa', 'Bali', 'Ubud', -8.5184, 115.2598, 5, 4.7, 1324, '["wifi","air_conditioning","dehumidifier","minifridge","pool","spa","restaurant","gym","yoga","river_view"]', '{"street":"Jl. Gunung Sari","city":"Ubud","state":"Bali","postal_code":"80571","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Luxurious riverside retreat surrounded by rice paddies and tropical forest.', 85),
('HB-DPS-RSL5DSDEMK', 'Komaneka at Bisma', 'Bali', 'Ubud', -8.5142, 115.2634, 4, 4.5, 876, '["wifi","air_conditioning","humidity_control","minifridge","pool","spa","restaurant","yoga","valley_view"]', '{"street":"Jl. Bisma","city":"Ubud","state":"Bali","postal_code":"80571","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Boutique hotel with stunning valley vistas and contemporary Balinese design.', 55),
('HB-DPS-MR6ZCIIM6J', 'Puri Wulandari', 'Bali', 'Ubud', -8.5298, 115.2587, 4, 4.4, 623, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","valley_view"]', '{"street":"Banjar Kedewatan","city":"Ubud","state":"Bali","postal_code":"80571","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Secluded hillside boutique resort with panoramic valley and jungle views.', 45),
('HB-DPS-QH4YBZOUDY', 'Bisma Eight', 'Bali', 'Ubud', -8.5156, 115.2647, 3, 4.2, 534, '["wifi","air_conditioning","minifridge","pool","restaurant","rooftop_bar","valley_view"]', '{"street":"Jl. Bisma","city":"Ubud","state":"Bali","postal_code":"80571","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Modern design hotel with rooftop pool and central Ubud location.', 50),
('HB-DPS-77367ZENTH', 'Sofitel Bali Nusa Dua Beach Resort', 'Bali', 'Nusa Dua', -8.7954, 115.2287, 5, 4.6, 1598, '["wifi","air_conditioning","dehumidifier","minifridge","pool","spa","restaurant","gym","beach_access","kids_club"]', '{"street":"Kawasan ITDC Nusa Dua","city":"Nusa Dua","state":"Bali","postal_code":"80363","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'French-inspired luxury resort with pristine beachfront and elegant facilities.', 140),
('HB-DPS-OGLCLVBHXZ', 'Hilton Bali Resort', 'Bali', 'Nusa Dua', -8.8012, 115.2301, 5, 4.5, 1432, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","beach_access","kids_club","waterslide"]', '{"street":"Kawasan ITDC Nusa Dua","city":"Nusa Dua","state":"Bali","postal_code":"80363","country":"Indonesia"}', '{"check_in":"15:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Family-friendly beachfront resort with extensive facilities and cliff-top setting.', 155),
('HB-DPS-LBTR2C7YLU', 'Melia Bali', 'Bali', 'Nusa Dua', -8.7987, 115.2294, 4, 4.3, 1124, '["wifi","air_conditioning","minifridge","pool","spa","restaurant","gym","beach_access","kids_club","garden"]', '{"street":"Kawasan ITDC Nusa Dua","city":"Nusa Dua","state":"Bali","postal_code":"80363","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Expansive resort with lush tropical gardens and direct beach access.', 165),
('HB-DPS-KIBVHBPOHH', 'Hyatt Regency Bali', 'Bali', 'Sanur', -8.6854, 115.2598, 4, 4.4, 1087, '["wifi","air_conditioning","humidity_control","minifridge","pool","spa","restaurant","gym","beach_access","kids_club"]', '{"street":"Jl. Danau Tamblingan","city":"Sanur","state":"Bali","postal_code":"80228","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Beachfront resort in tranquil Sanur with traditional Balinese architecture.', 130),
('HB-DPS-HPKVMYUFUD', 'Prama Sanur Beach Hotel', 'Bali', 'Sanur', -8.6912, 115.2621, 3, 3.9, 678, '["wifi","air_conditioning","minifridge","pool","restaurant","beach_access"]', '{"street":"Jl. Cemara","city":"Sanur","state":"Bali","postal_code":"80228","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Casual beachfront hotel offering relaxed atmosphere and Sanur beach access.', 100),
('HB-DPS-SK55IKAO7B', 'Lakeview Hotel Kintamani', 'Bali', 'Kintamani', -8.2425, 115.3754, 3, 3.7, 423, '["wifi","air_conditioning","minifridge","restaurant","volcano_view","hot_spring"]', '{"street":"Desa Batur","city":"Kintamani","state":"Bali","postal_code":"80652","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Mountain hotel at higher elevation with panoramic views of Mount Batur volcano and caldera lake.', 60),
('HB-DPS-WTC4SOQVVO', 'Batur Natural Hot Spring Resort', 'Bali', 'Kintamani', -8.2398, 115.3789, 3, 4, 512, '["wifi","air_conditioning","minifridge","pool","restaurant","hot_spring","volcano_view"]', '{"street":"Desa Toya Bungkah","city":"Kintamani","state":"Bali","postal_code":"80652","country":"Indonesia"}', '{"check_in":"14:00","check_out":"12:00","children_allowed":true,"pets_allowed":false}', 'Unique resort at volcano elevation featuring natural hot spring pools with Mount Batur views.', 70);
